const linhas = $input.all()
  .map(item => item.json)
  .filter(row => row && (row.remetente_nome || row.texto || row.links || row.timestamp));

if (linhas.length === 0) {
  return [{ json: { temAtividade: false } }];
}

const contagem = {};
const linksSet = new Set();
const textos = [];

for (const row of linhas) {
  const nome = row.remetente_nome || 'Desconhecido';
  contagem[nome] = (contagem[nome] || 0) + 1;

  if (row.links) {
    row.links.split(',').map(l => l.trim()).filter(Boolean).forEach(l => linksSet.add(l));
  }

  if (row.texto) {
    textos.push(`${nome}: ${row.texto}`);
  }
}

const top5 = Object.entries(contagem)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([nome, qtd], i) => `${i + 1}. ${nome} (${qtd} ${qtd === 1 ? 'msg' : 'msgs'})`)
  .join('\n');

return [{
  json: {
    temAtividade: true,
    top5,
    links: Array.from(linksSet).join('\n') || 'nenhum link na semana',
    textoConcatenado: textos.join('\n'),
  },
}];

