const DIAS = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho',
  'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const LINHA = '┈┈┈┈┈┈┈┈┈┈┈┈┈┈';

const emParagrafos = (texto) => texto
  .split(/\n+/)
  .map(paragrafo => paragrafo.trim())
  .filter(Boolean)
  .join('\n\n');

const inicio = $now.startOf('week');
const fim = $now;
const periodo = inicio.month === fim.month
  ? `${inicio.day} a ${fim.day} de ${MESES[fim.month - 1]}`
  : `${inicio.day} de ${MESES[inicio.month - 1]} a ${fim.day} de ${MESES[fim.month - 1]}`;

const resp = $input.first().json;
const resumoTopicos = emParagrafos(resp.content?.[0]?.text?.trim() || 'Não foi possível gerar o resumo da semana.');
const stats = $('Calcular estatísticas da semana').first().json;

const mensagemFinal = [
  '*📅 Resumo da semana*',
  `_SEU GRUPO AQUI · ${periodo}_`,
  '',
  LINHA,
  '',
  '*🗣️ Principais tópicos*',
  '',
  resumoTopicos,
  '',
  LINHA,
  '',
  '*🔗 Links compartilhados*',
  '',
  stats.links,
  '',
  LINHA,
  '',
  '*🏆 Top 5 da semana*',
  '',
  stats.top5,
].join('\n');

return [{ json: { mensagemFinal } }];

